<?php
function metric(string $label,float|int $value,string $format,string $direction='up'):array{return['label'=>$label,'value'=>round((float)$value,4),'format'=>$format,'direction'=>$direction];}
function top_items(array $items,string $key,int $limit=8):array{$o=[];foreach($items as $name=>$v)$o[]=['name'=>$name,'value'=>(float)($v[$key]??0),'quantity'=>(float)($v['quantity']??0)];usort($o,fn($a,$b)=>$b['value']<=>$a['value']);return array_slice($o,0,$limit);}
function named_total(array $items,string $wanted):float{foreach($items as $name=>$values)if(strcasecmp(trim((string)$name),trim($wanted))===0)return(float)($values['total']??0);return 0;}
