 $daily=$reports['daily_summary']['days']??[];$salesReport=$reports['sales_summary']??[];$sales=$salesReport['categories']??[];$salesTotals=$salesReport['totals']['categories']??[];$processing=$salesReport['payment_processing']??[];$appt=$reports['appointment_metrics']['providers']??[];$schedule=$reports['staff_schedule']??[];$svcP=$reports['service_commission']['providers']??[];$svcI=$reports['service_commission']['items']??[];$prodP=$reports['product_commission']['providers']??[];$memP=$reports['membership_commission']['providers']??[];$plans=$reports['membership_sales']['plans']??[];$retail=$reports['retail_product_sales']['products']??[];$allProducts=$reports['product_sales']['products']??[];$active=$reports['subscriptions']['active']??[];$mrr=(float)($reports['subscriptions']['active_mrr']??0);
 $sum=fn($key)=>array_sum(array_map(fn($row)=>(float)($row[$key]??0),$daily));
 $total=$sum('total_revenue');$service=$sum('service_revenue');$product=$sum('product_revenue');$membership=$sum('membership_revenue');$package=$sum('package_revenue');$tips=$sum('tip_revenue');$appointments=$sum('appointments');$requested=$sum('requested_appointments');
 $newClients=array_sum(array_map(fn($p)=>(float)$p['new_clients'],$appt));$scheduled=array_sum(array_map(fn($p)=>(float)$p['hours_scheduled'],$appt));$booked=array_sum(array_map(fn($p)=>(float)$p['hours_booked'],$appt));$util=$scheduled>0?$booked/$scheduled*100:0;$avg=$appointments>0?$total/$appointments:0;$revHour=$scheduled>0?$service/$scheduled:0;
 $retailRevenue=array_sum(array_map(fn($p)=>(float)$p['subtotal'],$retail));$retailUnits=array_sum(array_map(fn($p)=>(float)$p['quantity'],$retail));$membershipsSold=array_sum(array_map(fn($p)=>(float)$p['quantity'],$plans));
 $svcCom=array_sum(array_map(fn($p)=>(float)$p['commission'],$svcP));$prodCom=array_sum(array_map(fn($p)=>(float)$p['commission'],$prodP));$memCom=array_sum(array_map(fn($p)=>(float)$p['commission'],$memP));
 $netSales=(float)($salesTotals['total']??$total);$grossPayments=(float)($salesTotals['payments']??$netSales);$refunds=abs((float)($salesTotals['refunds']??0));$giftCards=named_total($sales,'Gift cards');$accountCredit=named_total($sales,'Account Credit');$tax=named_total($sales,'Tax');$voucherRevenue=named_total($sales,'Services Redeemed with Vouchers');$cardFees=abs(named_total($processing,'Card Fees'));$retailShare=$total>0?$retailRevenue/$total*100:0;
 $k=[
  'total_revenue'=>metric('Total Revenue',$total,'currency'),'net_sales'=>metric('Net Sales',$netSales,'currency'),'gross_payments'=>metric('Gross Payments',$grossPayments,'currency'),'refunds'=>metric('Refunds',$refunds,'currency','down'),
  'service_revenue'=>metric('Service Revenue',$service,'currency'),'product_revenue'=>metric('All Product Revenue',$product,'currency'),'retail_revenue'=>metric('Retail Revenue',$retailRevenue,'currency'),'retail_share'=>metric('% Retail Sales',$retailShare,'percent'),'membership_revenue'=>metric('Membership Revenue',$membership,'currency'),'package_revenue'=>metric('Package Revenue',$package,'currency'),'tips'=>metric('Tips',$tips,'currency','neutral'),
  'gift_cards_sold'=>metric('Gift Cards Sold',$giftCards,'currency'),'account_credit_sold'=>metric('Account Credit Sold',$accountCredit,'currency'),'tax_collected'=>metric('Tax Collected',$tax,'currency','neutral'),'voucher_revenue'=>metric('Services Redeemed with Vouchers',$voucherRevenue,'currency','neutral'),'card_fees'=>metric('Card Fees',$cardFees,'currency','down'),
  'appointments'=>metric('Total Appointments',$appointments,'number'),'requested_appointments'=>metric('Requested Appointments',$requested,'number'),'new_clients'=>metric('New Clients',$newClients,'number'),'utilization'=>metric('Blended Utilization',$util,'percent'),'average_ticket'=>metric('Average Revenue per Appointment',$avg,'currency'),'revenue_per_hour'=>metric('Revenue per Scheduled Hour',$revHour,'currency'),
