function compare_dashboard(array $current,?array $previous):array{foreach($current['kpis'] as $key=>&$m){$prev=$previous['kpis'][$key]['value']??null;$m['previous']=$prev===null?null:(float)$prev;if($prev===null){$m['change']=null;$m['percent_change']=null;$m['sentiment']='neutral';continue;}$change=(float)$m['value']-(float)$prev;$m['change']=$change;$m['percent_change']=abs((float)$prev)>.0001?$change/abs((float)$prev)*100:null;$dir=$m['direction']??'up';$m['sentiment']=$dir==='neutral'||abs($change)<.0001?'neutral':(($dir==='up'&&$change>0)||($dir==='down'&&$change<0)?'positive':'negative');}unset($m);return$current;}
function generate_insights(array $d):array{$k=$d['kpis']??[];$p=$d['providers']??[];$o=[];foreach([['total_revenue','Revenue','Revenue Optimization'],['appointments','Appointments','Operational Efficiency'],['active_mrr','Recurring revenue','Membership Growth'],['utilization','Utilization','Operational Efficiency'],['refunds','Refunds','Risk Management'],['retail_share','Retail contribution','Retail Performance']] as [$key,$name,$cat]){if(!isset($k[$key])||$k[$key]['previous']===null)continue;$m=$k[$key];$c=(float)$m['change'];$pc=$m['percent_change'];$direction=$c>0?'increased':($c<0?'decreased':'held steady');$priority=abs((float)$pc)>=15?'high':(abs((float)$pc)>=5?'medium':'low');$prev=match($m['format']){'currency'=>money($m['previous']),'percent'=>pct($m['previous']),default=>numfmt($m['previous'])};$o[]=['priority'=>$priority,'category'=>$cat,'title'=>$name.' '.$direction.($pc!==null?' by '.number_format(abs((float)$pc),1).'%':''),'observation'=>'Current: '.metric_display($m).'. Previous period: '.$prev.'.'];}
 if($p){$leader=$p[0];$total=array_sum(array_column($p,'service_revenue'));$share=$total>0?$leader['service_revenue']/$total*100:0;$o[]=['priority'=>$share>=50?'high':'medium','category'=>$share>=50?'Risk Management':'Provider Performance','title'=>$leader['name'].' led service revenue at '.money($leader['service_revenue']),'observation'=>$leader['name'].' generated '.number_format($share,1).'% of provider service revenue for this period.'.($share>=50?' Review provider concentration and capacity planning.':'')];$u=$p;usort($u,fn($a,$b)=>$b['utilization']<=>$a['utilization']);if(($u[0]['utilization']??0)>0)$o[]=['priority'=>'medium','category'=>'Operational Efficiency','title'=>$u[0]['name'].' led utilization at '.number_format($u[0]['utilization'],1).'%','observation'=>'Compare utilization with scheduled hours, appointments, and service revenue in the provider detail table.'];}
 $revenue=(float)($k['total_revenue']['value']??0);$retail=(float)($k['retail_revenue']['value']??0);if($revenue>0){$share=$retail/$revenue*100;$o[]=['priority'=>$share<5?'medium':'low','category'=>'Retail Performance','title'=>'Retail represented '.number_format($share,1).'% of total revenue','observation'=>'Retail-category sales were '.money($retail).' from '.numfmt($k['retail_units']['value']??0).' units.'];}
 $ops=$d['operations']??[];if(($ops['peak_hour_count']??0)>0)$o[]=['priority'=>'low','category'=>'Scheduling','title'=>'Peak client start time was '.$ops['peak_hour'],'observation'=>numfmt($ops['peak_hour_count']).' unique client appointments began in this time block. The busiest day was '.$ops['peak_day'].' with '.numfmt($ops['peak_day_count']).' scheduled clients.'];
